bool ray_vs_plane(Vector3 *xpoint, Vector3 const &p0, Vector3 const &dir, Plane3 const &plane)
{
 Vector3 n = plane.get_normal();
float denom = dot_product(n, dir);
 float epsilon = 0.0001f;
 if (fabs(denom) < epsilon) return false;
float t = - ((plane.d + dot_product(n, p0)) / denom);
 if (t < 0) return false;
*xpoint = p0 + dir * t;
 return true;
}
bool ray_vs_plane(Vector3 *xpoint, Vector3 const &p0, Vector3 const &dir, Vector3 const &plane_point, Vector3 const &plane_n)
{
 Vector3 local_p0 = p0 - plane_point;
float denom = dot_product(plane_n, dir);
 float epsilon = 0.0001f;
 if (fabs(denom) < epsilon) return false;
float t = - (dot_product(plane_n, local_p0) / denom);
 if (t < 0) return false;
*xpoint = p0 + dir * t;
 return true;
}

