 Vector3 p = object_to_world_space(grass, Vector3(cell_xy.x, cell_xy.y, 0.0f));
float max_r = Max(grass->r1, grass->r2);
 float gray = (cell_d / max_r);
 int unsigned color = argb_color(gray, gray, gray, 1);
 draw_circle(p, 0.1f, color);
}}
}}
}
}
